# TEST 4: 1D Local Linear (order=1)
# =============================================================================
results[[4]] <- run_test(
  "1D Order 1", "ref_1d_order1.mat", dx = 1, order = 1, type = "mean",
  function(mat) {
    x <- matrix(mat$x, ncol = 1)
    y <- matrix(mat$y, ncol = 1)
    hlist <- matrix(as.vector(mat$hlist), ncol = 1)

    # FIX 2025-12-01: Use MATLAB random vectors for exact DOF reproducibility
    opt <- list(order = 1, calc_dof = TRUE)
    if (!is.null(mat$dof.random.vectors)) {
      opt$dof_random_vectors <- mat$dof.random.vectors
    }

    res <- cv_fastlpr(x, y, hlist, opt)

    list(
      n = nrow(x),
      gcv_r = res$gcv_yhat$gcv_m, gcv_m = safe_extract(mat, "gcv_m"),
      bw_r = res$gcv_yhat$h1se, bw_m = as.numeric(mat$h1se),
      id_r = res$gcv_yhat$id1se, id_m = as.integer(mat$id1se),
      mean_r = as.vector(res$yhat), mean_m = safe_extract(mat, "yhat_mean"),
      var_r = NULL, var_m = NULL
    )
  }
)

