# =============================================================================
# TEST 9: Heteroscedastic 1D (mean + variance estimation)
# Two-step process: 1) estimate mean, 2) estimate variance from residuals^2
# =============================================================================
results[[9]] <- run_test(
  "Hetero 1D", "ref_hetero_1d.mat", dx = 1, order = 1, type = "mean+var",
  function(mat) {
    x <- matrix(mat$x, ncol = 1)
    y <- as.vector(mat$y)
    hlist <- matrix(as.vector(mat$hlist), ncol = 1)

    # Step 1: Estimate mean
    opt_mean <- list(order = 1, calc_dof = TRUE, dstd = 0)
    if (!is.null(mat$dof.random.vectors.mean)) {
      opt_mean$dof_random_vectors <- mat$dof.random.vectors.mean
    }
    res_mean <- cv_fastlpr(x, y, hlist, opt_mean)

    # Step 2: Estimate variance from residuals^2
    residuals <- y - res_mean$yhat
    opt_var <- list(order = 1, calc_dof = TRUE, y_type_out = "variance", dstd = 1)
    if (!is.null(mat$dof.random.vectors.var)) {
      opt_var$dof_random_vectors <- mat$dof.random.vectors.var
    }
    res_var <- cv_fastlpr(x, residuals^2, hlist, opt_var)

    list(
      n = nrow(x),
      gcv_r = res_mean$gcv_yhat$gcv_m, gcv_m = safe_extract(mat, "gcv_m"),
      bw_r = res_mean$gcv_yhat$h1se, bw_m = safe_extract(mat, "h1se_mean"),
      id_r = res_mean$gcv_yhat$id1se, id_m = as.integer(mat$id1se.mean),
      mean_r = as.vector(res_mean$yhat), mean_m = safe_extract(mat, "yhat_mean"),
      var_r = as.vector(res_var$yhat), var_m = safe_extract(mat, "yhat_var")
    )
  }
)

# =============================================================================
# TEST 10: Heteroscedastic 2D (mean + variance estimation)
# =============================================================================
results[[10]] <- run_test(
  "Hetero 2D", "ref_hetero_2d.mat", dx = 2, order = 1, type = "mean+var",
  function(mat) {
    x <- as.matrix(mat$x)
    y <- as.vector(mat$y)
    hlist <- as.matrix(mat$hlist)

    # Step 1: Estimate mean
    opt_mean <- list(order = 1, calc_dof = TRUE, dstd = 0)
    if (!is.null(mat$dof.random.vectors.mean)) {
      opt_mean$dof_random_vectors <- mat$dof.random.vectors.mean
    }
    res_mean <- cv_fastlpr(x, y, hlist, opt_mean)

    # Step 2: Estimate variance from residuals^2
    residuals <- y - res_mean$yhat
    opt_var <- list(order = 1, calc_dof = TRUE, y_type_out = "variance", dstd = 1)
    if (!is.null(mat$dof.random.vectors.var)) {
      opt_var$dof_random_vectors <- mat$dof.random.vectors.var
    }
    res_var <- cv_fastlpr(x, residuals^2, hlist, opt_var)

    list(
      n = nrow(x),
      gcv_r = res_mean$gcv_yhat$gcv_m, gcv_m = safe_extract(mat, "gcv_m"),
      bw_r = res_mean$gcv_yhat$h1se, bw_m = safe_extract(mat, "h1se_mean"),
      id_r = res_mean$gcv_yhat$id1se, id_m = as.integer(mat$id1se.mean),
      mean_r = as.vector(res_mean$yhat), mean_m = safe_extract(mat, "yhat_mean"),
      var_r = as.vector(res_var$yhat), var_m = safe_extract(mat, "yhat_var")
    )
  }
)

# =============================================================================
# GENERATE REPORT TABLE
# =============================================================================
cat("\n\n")
cat("================================================================================\n")
cat("   CROSS-VALIDATION REPORT TABLE\n")
cat("================================================================================\n\n")

# Header
cat(sprintf("%-12s | %5s | %2s | %5s | %8s | %8s | %8s | %6s | %10s | %10s | %10s | %10s | %10s | %10s | %10s | %10s | %6s\n",
            "Test", "N", "dx", "order", "Type", "MATLAB", "R Time", "Ratio",
            "GCV MaxErr", "GCV MSE", "BW MaxErr", "BW MSE",
            "Mean MaxErr", "Mean MSE", "Var MaxErr", "Var MSE", "Status"))
cat(paste(rep("-", 200), collapse = ""), "\n")

# Data rows
for (res in results) {
  cat(sprintf("%-12s | %5s | %2d | %5d | %8s | %8s | %8.3f | %6s | %10s | %10s | %10s | %10s | %10s | %10s | %10s | %10s | %6s\n",
              res$test,
              ifelse(is.na(res$n), "NA", as.character(res$n)),
              res$dx,
              res$order,
              res$type,
              ifelse(is.na(res$matlab_time), "NA", sprintf("%.3f", res$matlab_time)),
              ifelse(is.na(res$r_time), NA, res$r_time),
              ifelse(is.na(res$ratio), "NA", sprintf("%.2fx", res$ratio)),
              ifelse(is.na(res$gcv_max), "NA", sprintf("%.2e", res$gcv_max)),
              ifelse(is.na(res$gcv_mse), "NA", sprintf("%.2e", res$gcv_mse)),
              ifelse(is.na(res$bw_max), "NA", sprintf("%.2e", res$bw_max)),
              ifelse(is.na(res$bw_mse), "NA", sprintf("%.2e", res$bw_mse)),
              ifelse(is.na(res$mean_max), "NA", sprintf("%.2e", res$mean_max)),
              ifelse(is.na(res$mean_mse), "NA", sprintf("%.2e", res$mean_mse)),
              ifelse(is.na(res$var_max), "NA", sprintf("%.2e", res$var_max)),
              ifelse(is.na(res$var_mse), "NA", sprintf("%.2e", res$var_mse)),
              res$status))
}

cat(paste(rep("-", 200), collapse = ""), "\n")

# Summary
n_pass <- sum(sapply(results, function(r) r$status == "PASS"))
n_fail <- sum(sapply(results, function(r) r$status == "FAIL"))
n_error <- sum(sapply(results, function(r) r$status == "ERROR"))
n_skip <- sum(sapply(results, function(r) r$status == "SKIP"))
total <- length(results)

cat(sprintf("\nSUMMARY: %d PASS, %d FAIL, %d ERROR, %d SKIP (Total: %d)\n",
            n_pass, n_fail, n_error, n_skip, total))

if (n_pass == total) {
  cat("\n*** ALL TESTS PASSED ***\n")
} else if (n_skip > 0) {
  cat("\n*** SOME TESTS SKIPPED - Run MATLAB reference generation first ***\n")
  cat("  matlab -batch \"run('verification/generate_cross_validation_refs.m')\"\n")
} else if (n_fail > 0 || n_error > 0) {
  cat("\n*** SOME TESTS FAILED - INVESTIGATION NEEDED ***\n")
}

# Save results
saveRDS(results, "verification/cross_validation_results_r.rds")
cat("\nResults saved to: verification/cross_validation_results_r.rds\n")

cat("\n================================================================================\n")
cat("Done!\n")

# Return non-zero exit code if any tests failed
if (n_fail > 0 || n_error > 0) {
  quit(status = 1)
}
